insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4ee75fb2-aac7-44a3-9202-4550f72c6d30', 'situacion', 'DEADPOOL · Pregunta 1', 'ctx-sit', '<p>En un colegio, una materia se aprueba con una nota final de 3,0 o más, sin usar redondeo. El profesor usa varias estrategias de ponderación. Un estudiante tiene estas notas: talleres 3,0; examen 2,0; participación en clase 3,0.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('103a4fda-3131-4df8-80b5-bc1d00b1fdf4', 'situacion', 'DEADPOOL · Pregunta 2', 'ctx-sit', '<p>En un ecosistema habitan solamente sapos, saltamontes, lagartijas y serpientes. Solamente los sapos y las lagartijas se camuflan.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('851a3a7d-24f0-4123-86fa-41b3d1eceff4', 'situacion', 'DEADPOOL · Pregunta 3', 'ctx-sit', '<p>La tabla muestra la producción de leche durante cinco días de una semana.</p><figure class="ctx-fig"><img src="img/figuras/mat/de1-q03-tabla.webp" alt="Lunes 75 litros, martes 65, miércoles 75, jueves 65, viernes 70." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('5fbe73c7-1e5c-45fa-94f7-bfd8bd39d70d', 'situacion', 'DEADPOOL · Pregunta 4', 'ctx-sit', '<p>Una empresa establece precios para carteles rectangulares de 4 metros de ancho y 2 metros de alto, de acuerdo con el área ocupada por imagen y texto.</p><figure class="ctx-fig"><img src="img/figuras/mat/de1-q04-precios.webp" alt="Imagen: por cada 1 % del área total, $50.000. Texto: por cada 5 %, $100.000." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b2d2f540-a8d5-46d0-aa99-78ff14a303ee', 'situacion', 'DEADPOOL · Pregunta 5', 'ctx-sit', '<p>Se quiere construir un carril paralelo a una carretera. Se representa la carretera como el eje horizontal y se ubica M(2,1). Desde un punto N del eje vertical se traza una circunferencia que pasa por M y corta el eje vertical en P y Q. Con centro en P se traza otra circunferencia que pasa por M e interseca la primera también en R. La recta MR será el nuevo carril.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f8881c3f-d07f-4912-9bb8-ec30a7a80a8f', 'situacion', 'DEADPOOL · Pregunta 6', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q06-tabla.webp" alt="Cucharadas de azúcar: Carlos 1, Juliana 5, Lorena 3, Iván 1, Patricia 0." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f738100c-1e32-4716-9f31-be38d6ca5d33', 'situacion', 'DEADPOOL · Pregunta 7', 'ctx-sit', '<p>Se encuestó a profesores sobre edad, estado civil, horas trabajadas semanalmente y título universitario. Se propone hallar el rango estadístico de cada variable seleccionada, sumar esos rangos y dividir entre el número de variables.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('c29f8501-5451-4233-bb71-ec3930d36e0e', 'situacion', 'DEADPOOL · Pregunta 8', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q08-tabla.webp" alt="Edad en años y minutos: 14→28, 15→30, 19→38, 20→40." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7af2cea2-6ca6-40ab-a28c-e2c95e476474', 'situacion', 'DEADPOOL · Pregunta 9', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q09-consumo.webp" alt="Consumo de mayo a octubre: 82, 60, 82, 90, 82 y 66 kWh. También se muestra una barra de consumo promedio de 77 kWh." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9148b992-1973-4b79-82c3-81ea3fe99f33', 'situacion', 'DEADPOOL · Pregunta 10', 'ctx-sit', '<p>El techo de una casa está formado por seis caras triangulares iguales. Para hallar el área se multiplica la base por la altura de un triángulo, se divide entre 2 y se multiplica por 6. El resultado es 72 m².</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('1f73913d-4e5e-4627-8587-0ff89e3170b5', 'situacion', 'DEADPOOL · Pregunta 11', 'ctx-sit', '<p>Lucía debe configurar la inclinación de un telescopio a 30°, pero el sistema digital recibe el ángulo en radianes.</p><figure class="ctx-fig"><img src="img/figuras/mat/de1-q11-telescopio.webp" alt="Telescopio formando un ángulo de 30 grados respecto a la horizontal." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('26d64ab9-73f0-44d8-bd00-6139a3673252', 'situacion', 'DEADPOOL · Pregunta 12', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q12-tarifas.webp" alt="Opción 1: entrada $20.000 y $1.000 por atracción. Opción 2: entrada $15.000 y $1.200 por atracción." loading="lazy"></figure><p>Si x es la cantidad de atracciones, una persona plantea 20.000 + 1.000x &lt; 15.000 + 1.200x.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('c90d5a32-7816-4ddb-8d75-031aeeba82e6', 'situacion', 'DEADPOOL · Pregunta 13', 'ctx-sit', '<p>Se encuestó a diez asistentes de un gimnasio sobre su edad y el número de compras mensuales de ropa deportiva.</p><figure class="ctx-fig"><img src="img/figuras/mat/de1-q13-tabla.webp" alt="Edades: 18,25,23,35,36,18,19,31,32,27. Compras mensuales: 3,2,3,2,1,4,2,1,2,3." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('eb414178-f20c-4ce6-b860-d4af507a5251', 'situacion', 'DEADPOOL · Pregunta 15', 'ctx-sit', '<p>Un profesor escribe f(x) = (x² − 9)/(x + 3). Paso 1: plantear x + 3 = 0. Paso 2: resolver esa ecuación. Paso 3: considerar todos los números reales menos el valor encontrado.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('88acfa6c-ea57-415b-a5f1-f5fb147f2bde', 'situacion', 'DEADPOOL · Pregunta 16', 'ctx-sit', '<p>Se registraron las tallas de zapatos de 41 estudiantes. La mediana es 36.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('40f8b2b1-20b0-4885-85bb-fad94551f3ed', 'situacion', 'DEADPOOL · Pregunta 17', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q17-piramide.webp" alt="Pirámide de base cuadrilateral. Se considera una sección transversal paralela a la base, distinta de ella." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('54d7bb1d-fa71-4c00-b53c-f08ef3ca0cf2', 'situacion', 'DEADPOOL · Pregunta 18', 'ctx-sit', '<p>Un atleta recorre un camino recto a velocidad constante de 4 m/s y su posición inicial es distinta de cero. x representa posición en metros y t tiempo en segundos.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b4bc2397-2c73-413c-8cc8-8142456fd941', 'situacion', 'DEADPOOL · Pregunta 19', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q19-antena.webp" alt="La cobertura es un círculo. Su centro es el vértice común de dos torres cuadradas. La torre P ocupa un cuadrante con lado igual al radio; la diagonal de la torre Q equivale al radio." loading="lazy"></figure><p>Dentro de las torres no hay señal. Un técnico afirma que conociendo el lado de Q puede determinar el área con cobertura.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('38785578-b2b2-41db-ab11-b9f38f3a5b4b', 'situacion', 'DEADPOOL · Pregunta 20', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q20-tabla.webp" alt="Movilidad semanal: Pepe 50,45,40,35,30 %; Jacinto 20,30,40,20,30 %; Juan 35,40,45,50,55 %; María 10,20,20,20,50 %." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a14b0b0f-9166-434a-928e-9d9ea17cb234', 'situacion', 'DEADPOOL · Pregunta 21', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q21-tabla.webp" alt="Triángulos rectángulos: V tiene base 1 cm y altura 3 cm; W base 4 y altura 4; Z base 3 y altura 4." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f153e4c0-4f3e-4f0e-953e-59f0bd3595ef', 'situacion', 'DEADPOOL · Pregunta 22', 'ctx-sit', '<p>Un niño gana una consola si gana dos juegos independientes: obtener un número par al lanzar un dado (probabilidad 1/2) y sacar la única pelota amarilla de una bolsa de seis (probabilidad 1/6). Se proponen: 1. sumar las probabilidades de ganar; 2. multiplicarlas; 3. restar de 1 la probabilidad de perder al menos un juego; 4. restar de 1 la probabilidad de perder exactamente un juego.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b67ce2ca-c2c5-47fb-baae-eeebd0907728', 'situacion', 'DEADPOOL · Pregunta 23', 'ctx-sit', '<p>Se requieren 45 cuadrados para construir una figura, pero se usarán solo 30.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('485d7b97-649e-4bf6-98fc-e80ff2fd9cd8', 'situacion', 'DEADPOOL · Pregunta 24', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q24-cafe.webp" alt="Frasco de café cuyo rótulo indica: rinde 3.200 cm³ de café." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('1e6f7e29-32b7-4d12-9427-10bf86c02b68', 'situacion', 'DEADPOOL · Pregunta 25', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q25-dias.webp" alt="Número de encuestadores 1,3,5,6,10; días necesarios 150,50,30,25,15." loading="lazy"></figure><figure class="ctx-fig"><img src="img/figuras/mat/de1-q25-costo.webp" alt="El costo diario aumenta proporcionalmente con los encuestadores: 2 cuestan $70.000, 4 cuestan $140.000, 6 cuestan $210.000 y 10 cuestan $350.000." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('981dbc60-d828-4a74-93da-435bce09939a', 'situacion', 'DEADPOOL · Pregunta 26', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q26-tubo.webp" alt="Tubo cilíndrico con base circular y altura." loading="lazy"></figure><p>Para calcular el aluminio necesario para rellenarlo, Antonio mide la altura, mide el perímetro de la base y multiplica ambas medidas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9484e7f5-9838-4d1b-b3fb-2015f477e36f', 'situacion', 'DEADPOOL · Pregunta 27', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q27-cuadrados.webp" alt="Cuadrado PQRS: P abajo a la izquierda, Q abajo a la derecha, R arriba a la derecha, S arriba a la izquierda. La diagonal PR es un lado de un segundo cuadrado PRTU, que se extiende hacia arriba y a la izquierda." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('c44f65cb-31d8-4a8d-905c-e4ab23849117', 'situacion', 'DEADPOOL · Pregunta 28', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q28-notas.webp" alt="Seis estudiantes: intensidad horaria 3,4,6,7,8,12; tareas 8,6,5,4,2,1; notas de matemáticas 3,9;4,0;4,2;4,5;4,6;4,8; química 4,0;3,9;3,7;3,5;3,0;2,9." loading="lazy"></figure><p>Se plantean: 1. a mayor intensidad horaria, mejores notas en matemáticas; 2. a mayor número de tareas, menores notas en matemáticas; 3. a menor intensidad horaria, más bajas notas en química; 4. a mayor número de tareas, mejor nota de matemáticas y química.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('eff068fd-14eb-4adf-ac6d-006714715ed4', 'situacion', 'DEADPOOL · Pregunta 29', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q29-notas.webp" alt="Carlos: notas 1,5,9 y desviación estándar 4. Miguel: 3,2,8 y desviación 3,2. Claudia: 4,5,6 y desviación 1." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('1c76bc72-f194-4bdc-a180-cfcd3877d933', 'situacion', 'DEADPOOL · Pregunta 30', 'ctx-sit', '<p>De 82 estudiantes, 55 juegan fútbol y 46 baloncesto. Los que juegan ambos deportes son el doble de los que no juegan ninguno. Si 19 no practican ninguno, ¿qué diagrama representa la información?</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f559eb3c-d284-439c-8a4c-e9ac1c839cfd', 'situacion', 'DEADPOOL · Pregunta 31', 'ctx-sit', '<p>Un jugador empieza con dos fichas. Cada giro de una ruleta duplica sus fichas o le quita una. Tiene hasta tres giros mientras conserve fichas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('2dcd1a2c-de86-435e-bd62-29f163998098', 'situacion', 'DEADPOOL · Pregunta 32', 'ctx-sit', '<p>Marcos recibe seis tarros de pintura de colores diferentes y debe escoger tres sin repetir color. Se proponen: 1. dividir seis entre tres; 2. hallar 6! y dividir entre tres; 3. contar las formas de escoger tres colores diferentes entre seis; 4. hallar las combinaciones de tres elementos de un conjunto de seis.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('483dde53-9eab-42f2-99c8-082c14ab0e9e', 'situacion', 'DEADPOOL · Pregunta 14', 'ctx-sit', '<p>Un grupo de ingenieros quiere calcular la altura h de un edificio. El original anuncia dos procedimientos, pero solo muestra «Procedimiento 1: tan 60 = h» y no contiene la figura ni el segundo procedimiento.</p><figure class="ctx-fig"><img src="img/figuras/mat/de1-q14-fuente-incompleta.webp" alt="Captura del ejercicio original: falta la figura anunciada y solo aparece el primer procedimiento." loading="lazy"></figure>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'bd08c36b-6d4b-4697-9360-8f5fef809a1e', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  '4ee75fb2-aac7-44a3-9202-4550f72c6d30', 'Estadística descriptiva',
  '¿Con cuál de las siguientes estrategias de ponderación el estudiante aprobaría la materia?',
  array['Sumar las 3 notas y dividir el resultado entre 3.', 'Promediar talleres y participación, multiplicar el resultado por 0,9 y sumarle la nota de participación multiplicada por 0,1.', 'Promediar examen y participación, multiplicar por 0,1 y sumarle la nota de talleres multiplicada por 0,9.', 'Promediar las 3 notas y sumarle 0,1.'],
  'Calcula cada resultado sin redondear y compáralo con la nota mínima.', 'publicada', 'modelo', 'c717577fec3fc7ac3c2500befc8e83f6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('bd08c36b-6d4b-4697-9360-8f5fef809a1e', 1, 'El promedio de talleres y participación es 3. Al ponderarlo se obtiene 3×0,9 + 3×0,1 = 3,0. Las otras estrategias dan 8/3, 2,95 y 8/3 + 0,1, respectivamente: todas menores que 3,0.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a6f1271e-cd4e-404e-a7ed-539020949994', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'tablas-y-probabilidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '103a4fda-3131-4df8-80b5-bc1d00b1fdf4', 'Tablas y probabilidad',
  '¿Con cuáles datos se puede calcular la probabilidad de que un animal seleccionado al azar se camufle?',
  array['La cantidad de lagartijas, sapos y serpientes.', 'La cantidad de sapos, serpientes y saltamontes.', 'La cantidad de saltamontes, lagartijas y animales del ecosistema.', 'La cantidad de serpientes, saltamontes y animales del ecosistema.'],
  'También puedes calcular una probabilidad restando de 1 la del evento contrario.', 'publicada', 'modelo', 'c386eebe7b5bfd50e3f788a6a00de542', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a6f1271e-cd4e-404e-a7ed-539020949994', 3, 'Los casos favorables son sapos y lagartijas. Si se conoce el total N y los dos grupos que no se camuflan, se obtiene P = (N − serpientes − saltamontes)/N. Las otras listas dejan desconocido el total o uno de los grupos necesarios.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ce6068e3-08c9-4c6d-b450-a09a04e11fb5', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  '851a3a7d-24f0-4123-86fa-41b3d1eceff4', 'Estadística descriptiva',
  'Una persona afirma que las vacas produjeron, en promedio, 70 litros diarios. ¿Es verdadera esta afirmación?',
  array['Sí, porque el viernes produjeron 70 litros de leche.', 'No, porque solamente produjeron 70 litros de leche un día.', 'Sí, porque la producción total es igual a 70 litros multiplicados por el número de días.', 'No, porque miércoles y jueves la producción fue menor de 70 litros.'],
  'Promedio = suma de los valores dividida entre la cantidad de datos.', 'publicada', 'modelo', '3bf51f56c9f7e2919ba122812bbc3a34', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ce6068e3-08c9-4c6d-b450-a09a04e11fb5', 2, 'La suma es 350 litros. Al dividir entre cinco días resulta 70. Que un día coincida con 70 no demuestra el promedio; es necesario usar todos los días.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
