insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7e38b5ef-0b3b-4a9a-8432-100eaa6968f5', 3, 'El cartel mide 8 m² = 80.000 cm². Su 1 % es 800 cm² y su 5 % es 4.000 cm². Deben conservarse simultáneamente esas dos áreas y sus precios.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
