  array['<figure class="ctx-fig"><img src="img/figuras/mat/de1-q05-a.webp" alt="Circunferencias con intersecciones R y M sobre la recta horizontal de altura 2." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q05-b.webp" alt="Dos circunferencias con centros N y P en el eje vertical; M(2,1) y R comparten la recta horizontal de altura 1." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q05-c.webp" alt="Los centros de las circunferencias se ubican en el eje horizontal." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q05-d.webp" alt="M está cerca de (1,2) y la recta MR es vertical." loading="lazy"></figure>'],
  'Verifica primero las coordenadas dadas y después la posición de los centros.', 'publicada', 'modelo', 'b9cc91ec15057e0a949b7b9931c093f3', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ecb3486d-83cb-4c15-99a5-4a1cd4f59363', 1, 'M debe ser (2,1), ambos centros deben estar en el eje vertical y la recta que une las intersecciones debe ser horizontal. Por simetría respecto al eje vertical, R está al mismo nivel que M. Solo un plano satisface esas condiciones juntas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7fa4b28b-9703-4d3b-b04f-0ac79e7830db', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  'f8881c3f-d07f-4912-9bb8-ec30a7a80a8f', 'Estadística descriptiva',
  'En promedio, ¿cuántas cucharadas de azúcar le ponen a su café los cinco profesores?',
  array['1 cucharada.', '2 cucharadas.', '3 cucharadas.', '5 cucharadas.'],
  'El cero también es un dato y cuenta en el denominador.', 'publicada', 'modelo', '21c3d2d40a27d0413cf9b62368aba453', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7fa4b28b-9703-4d3b-b04f-0ac79e7830db', 1, 'Las cantidades suman 1 + 5 + 3 + 1 + 0 = 10. Hay cinco profesores, incluido quien no usa azúcar: 10/5 = 2.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '183e19a6-8edd-4d0c-8d74-7e6c8d88369f', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  'f738100c-1e32-4716-9f31-be38d6ca5d33', 'Estadística descriptiva',
  '¿Con cuáles variables se puede realizar el procedimiento?',
  array['Edad y estado civil.', 'Edad y número de horas que trabajan semanalmente.', 'Título universitario y estado civil.', 'Título universitario y número de horas que trabajan semanalmente.'],
  'Antes de operar, distingue variables numéricas de categorías.', 'publicada', 'modelo', 'c40e1bd9ec696b8a2715ab8fcd75aded', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('183e19a6-8edd-4d0c-8d74-7e6c8d88369f', 1, 'El rango exige restar un mínimo de un máximo. Edad y horas son variables numéricas; estado civil y título son categorías sin una resta numérica definida.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1e09cd16-2d9f-439c-bd04-a1a2fe2327a7', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  'c29f8501-5451-4233-bb71-ec3930d36e0e', 'Funciones y variación',
  '¿Qué se puede afirmar correctamente sobre los minutos necesarios para resolver el problema?',
  array['Son directamente proporcionales a la edad, porque es constante su producto con la edad.', 'Son inversamente proporcionales a la edad, porque es constante su producto con la edad.', 'Son directamente proporcionales a la edad, porque son el doble de la edad correspondiente.', 'Son inversamente proporcionales a la edad, porque son el doble de la edad correspondiente.'],
  'En proporción directa el cociente es constante; en inversa lo es el producto.', 'publicada', 'modelo', '8ce047be2fe9f86264c4ef6591c058cf', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1e09cd16-2d9f-439c-bd04-a1a2fe2327a7', 2, 'En todos los casos minutos/edad = 2. La relación es m = 2e, una proporcionalidad directa. Lo constante es el cociente, no el producto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a8e7dd7c-a721-407c-b78f-e9c139abafec', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  '7af2cea2-6ca6-40ab-a28c-e2c95e476474', 'Estadística descriptiva',
  '¿Cuál es el rango del consumo de energía de los últimos seis meses?',
  array['30', '60', '77', '82'],
  'Para el rango solo necesitas los valores extremos.', 'publicada', 'modelo', '5a84465269deb6352fbe878a7e809fc9', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a8e7dd7c-a721-407c-b78f-e9c139abafec', 0, 'El máximo es 90 y el mínimo 60: rango = 90 − 60 = 30 kWh. El promedio de 77 es otra medida.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5fccfe57-85c3-4a2d-acc0-9405fbefc55c', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
