  array['Altura: 3 m y base: 4 m.', 'Altura: 4 m y base: 6 m.', 'Altura: 5 m y base: 7 m.', 'Altura: 2 m y base: 3 m.'],
  'Calcula primero el área de una cara, no la de todo el techo.', 'publicada', 'modelo', 'ad0b20c8d61021576b2ce3b2c29e0afc', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5fccfe57-85c3-4a2d-acc0-9405fbefc55c', 1, 'Cada cara tiene 72/6 = 12 m². Su base por altura debe dar 24, pues el área es bh/2. La pareja 6 m y 4 m cumple: 6×4/2 = 12.');

