insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8fa6d625-703a-41be-ab07-d28af5e61e0c', 0, 'Como 180° equivalen a π radianes, 30° × π/180° = π/6 rad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
