  '26d64ab9-73f0-44d8-bd00-6139a3673252', 'Funciones y variación',
  '¿Qué problema se puede resolver con esa desigualdad?',
  array['El costo total mínimo que se debe pagar si se elige la opción 1.', 'El número máximo de atracciones para que el costo con la opción 1 sea menor que con la opción 2.', 'El número mínimo de atracciones para que el costo con la opción 1 sea menor que con la opción 2.', 'El costo total máximo que se puede pagar por la opción 2.'],
  'Comprueba si la solución impone un límite inferior o superior.', 'publicada', 'modelo', '7f5631a1b79b6a0a8d6652caa8d5a758', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('14af716d-f7c2-4174-af83-c2ce8376b491', 2, 'La desigualdad se reduce a 5.000 < 200x, es decir, x > 25. Al ser un conteo, desde 26 atracciones la primera opción es más barata. Determina un mínimo, no un máximo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
