insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('60002782-845c-4d02-ae67-094e623c3212', 2, 'Se conocen los diez conteos de compras y se puede obtener su promedio: 23/10 = 2,3. No se conoce cuántas prendas hubo por compra ni se encuestó necesariamente a todos los clientes.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
