  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  'eb414178-f20c-4ce6-b860-d4af507a5251', 'Funciones y variación',
  '¿Para qué sirven los pasos?',
