insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d6ee293a-a4e3-4c0c-8155-adb9c57ad386', 0, 'El denominador no puede ser cero: x ≠ −3. Por tanto, el dominio es el conjunto de reales excluyendo −3. Aunque se simplifique la expresión, esa restricción original permanece.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
