  array['<figure class="ctx-fig"><img src="img/figuras/mat/de1-q16-a.webp" alt="Tallas 34,35,36,37,38 con frecuencias 9,13,15,3,1." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q16-b.webp" alt="Tallas 34,35,36,37,38 con frecuencias 8,8,1,12,12." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q16-c.webp" alt="Tallas 34,35,36,37,38 con frecuencias 2,5,8,11,15." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q16-d.webp" alt="Tallas 34,35,36,37,38 con frecuencias 6,13,9,7,6." loading="lazy"></figure>'],
