insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4e28919e-a571-4c2a-8522-b942764dad25', 3, 'La mediana ocupa la posición 21. Con frecuencias 6,13,9,7,6, las primeras 19 observaciones son menores que 36 y las posiciones 20 a 28 valen 36. En las otras distribuciones la posición 21 corresponde a 35 o 37.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
