  (select id from public.lotes where codigo = '2026-B'),
  '40f8b2b1-20b0-4885-85bb-fad94551f3ed', 'Áreas y perímetros',
  'La intersección de la pirámide con un plano paralelo a la base que no la contiene es un cuadrilátero',
  array['con ángulos diferentes e igual área que la base.', 'con ángulos iguales y diferente área que la base.', 'con ángulos diferentes y diferente área que la base.', 'con ángulos iguales e igual área que la base.'],
  'Semejanza conserva ángulos; no exige el mismo tamaño.', 'publicada', 'modelo', 'b6223248d6d4316db4eec98a47d6394b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('567d2791-b624-4bea-902e-a9b70c153564', 1, 'Una sección paralela a la base de una pirámide es semejante a ella. Conserva los ángulos y cambia la escala de las longitudes; por eso su área es diferente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '892658a7-26a3-4a57-bf4d-9f6240e47a2d', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  '54d7bb1d-fa71-4c00-b53c-f08ef3ca0cf2', 'Funciones y variación',
