  'Compara diferencias consecutivas y revisa el valor inicial.', 'publicada', 'modelo', 'dfa9761d5c6c3a09ae67a6e7968c4802', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('892658a7-26a3-4a57-bf4d-9f6240e47a2d', 1, 'Una velocidad de 4 m/s exige aumentar la posición en 4 cada segundo. La sucesión 3,7,11,15 cumple x = 3 + 4t y empieza en una posición no nula.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '935c2556-9066-439b-9f08-4705da4da067', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  'b4bc2397-2c73-413c-8cc8-8142456fd941', 'Áreas y perímetros',
  '¿Es verdadera la afirmación?',
  array['No, porque también necesita el lado de P y no se puede calcular a partir del lado de Q.', 'Sí, porque con el lado de Q puede determinar las áreas del círculo, de Q y del sector ocupado por P.', 'No, porque es imposible calcular cuánto bloquea P.', 'Sí, porque puede restar al círculo las áreas completas de las bases de P y Q.'],
  'Resta solo las partes de los obstáculos que están dentro del área de cobertura.', 'publicada', 'modelo', '18e3f3e373fed051623883951305fdf1', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('935c2556-9066-439b-9f08-4705da4da067', 1, 'Si Q tiene lado a, el radio es a√2. Dentro del círculo, P bloquea un cuarto del área circular, no su cuadrado completo. La cobertura es π(2a²) − π(2a²)/4 − a². Todo se determina a partir de a.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a427701b-89bf-4015-bb1b-4bd3da6fc406', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  '38785578-b2b2-41db-ab11-b9f38f3a5b4b', 'Interpretación de datos',
  '¿Cuál paciente presentó un comportamiento lineal creciente durante las cinco semanas?',
  array['Pepe.', 'María.', 'Juan.', 'Juancho.'],
  'Lineal creciente significa sumar la misma cantidad positiva en cada intervalo igual.', 'publicada', 'modelo', 'cf56e163d625d24d1f374e368c4b06ad', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a427701b-89bf-4015-bb1b-4bd3da6fc406', 2, 'Juan aumenta exactamente cinco puntos porcentuales cada semana. Pepe disminuye y las otras series no tienen incrementos constantes.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c93e80b3-0aa8-495c-939f-346163a34a4a', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  'a14b0b0f-9166-434a-928e-9d9ea17cb234', 'Áreas y perímetros',
  '¿Cuál representación permite calcular las áreas sin ayuda de la tabla?',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/de1-q21-a.webp" alt="Tres triángulos rectángulos en cuadrícula con catetos de 1 y 3, de 4 y 4, y de 3 y 4 unidades." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q21-b.webp" alt="Tres triángulos con catetos que no coinciden con todos los valores de la tabla." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q21-c.webp" alt="Tres triángulos con catetos de 1 y 4, de 4 y 4, y de 2 y 2 unidades." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q21-d.webp" alt="Tres triángulos con dimensiones distintas de las tres parejas de la tabla." loading="lazy"></figure>'],
  'Cuenta intervalos de la cuadrícula, no la cantidad de marcas.', 'publicada', 'modelo', '644213bc200a5d501f5a76ae31f9679e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c93e80b3-0aa8-495c-939f-346163a34a4a', 0, 'Se deben contar los desplazamientos horizontal y vertical de los catetos: las parejas requeridas son (1,3), (4,4) y (3,4). Sus áreas son 1,5, 8 y 6 cm². La ubicación en otro cuadrante no cambia esas longitudes.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '348cffd1-c24b-4807-a8f7-cd90dfdacfc2', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'tablas-y-probabilidad'),
  (select id from public.lotes where codigo = '2026-B'),
  'f153e4c0-4f3e-4f0e-953e-59f0bd3595ef', 'Tablas y probabilidad',
  '¿Cuáles procedimientos permiten hallar la probabilidad de ganar la consola?',
  array['1 y 3.', '1 y 4.', '2 y 3.', '2 y 4.'],
  'El complemento de ganar todos es perder al menos uno.', 'publicada', 'modelo', 'fa5cc114f7d61f9773ace6943c338eee', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('348cffd1-c24b-4807-a8f7-cd90dfdacfc2', 2, 'Ganar ambos tiene probabilidad (1/2)(1/6)=1/12. Su complemento es perder al menos uno. Perder exactamente uno excluye el caso de perder los dos, por lo que su complemento no es solo ganar ambos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '579d9731-a586-4b20-954d-c662a006b892', 'mat',
