  'b67ce2ca-c2c5-47fb-baae-eeebd0907728', 'Proporcionalidad y porcentajes',
  '¿A qué fracción de la cantidad requerida equivale la cantidad que se usará?',
  array['1/3', '3/2', '2/3', '1/2'],
  'La cantidad de referencia va en el denominador.', 'publicada', 'modelo', '201e48d6b393f136dcf4c21d26d3e65e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('579d9731-a586-4b20-954d-c662a006b892', 2, 'La fracción es 30/45. Dividiendo numerador y denominador entre 15 resulta 2/3.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '51afe259-1b06-47a4-a0d9-774ecb785ebf', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '485d7b97-649e-4bf6-98fc-e80ff2fd9cd8', 'Proporcionalidad y porcentajes',
  '¿Cuántos litros de café puede preparar Eliana con el contenido del frasco?',
  array['320 litros.', '32 litros.', '3,2 litros.', '0,32 litros.'],
  'Al convertir cm³ a litros divide entre mil.', 'publicada', 'modelo', 'ec32bc3cc2eae45d8627675c164dcd59', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('51afe259-1b06-47a4-a0d9-774ecb785ebf', 2, 'Un litro equivale a 1.000 cm³; 3.200/1.000 = 3,2 litros.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a2202300-cbe0-44d8-92aa-0225bc10536a', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '1e6f7e29-32b7-4d12-9427-10bf86c02b68', 'Proporcionalidad y porcentajes',
  '¿Cuál afirmación describe las relaciones entre las variables?',
  array['Días y encuestadores son inversamente proporcionales; encuestadores y costo diario son directamente proporcionales.', 'Días y encuestadores son directamente proporcionales; encuestadores y costo diario son inversamente proporcionales.', 'Ambas relaciones son inversamente proporcionales.', 'Ambas relaciones son directamente proporcionales.'],
  'Busca producto constante para una relación inversa y cociente constante para una directa.', 'publicada', 'modelo', '0c163259b9a034923a939a27f003cc55', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a2202300-cbe0-44d8-92aa-0225bc10536a', 0, 'El producto de días por encuestadores siempre es 150. En cambio, costo diario/encuestadores siempre es $35.000. La primera relación es inversa y la segunda directa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '17ecc070-4e09-42af-a980-5b4871449b13', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'geometria-espacial'),
  (select id from public.lotes where codigo = '2026-B'),
  '981dbc60-d828-4a74-93da-435bce09939a', 'Geometría espacial',
  '¿En cuál paso hay un error?',
  array['En el paso 2, porque debe medirse el radio y no el perímetro.', 'En el paso 1, porque debe medirse la diagonal y no la altura.', 'En el paso 2, porque debe medirse el área y no el perímetro.', 'En el paso 1, porque debe medirse el ancho y no la altura.'],
  'Volumen = área de la base × altura.', 'publicada', 'modelo', '9ef2984bd7c2159482f619e19c39879f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('17ecc070-4e09-42af-a980-5b4871449b13', 2, 'El volumen de un cilindro es área de la base por altura. Perímetro por altura produce un área lateral, no la cantidad de material que cabe dentro. Medir el radio solamente tampoco basta sin elevarlo al cuadrado y multiplicar por π.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '12dbd5e2-73e6-4fcd-ad7a-ddfe7435485c', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  '9484e7f5-9838-4d1b-b3fb-2015f477e36f', 'Áreas y perímetros',
  '¿Cuál relación es correcta?',
  array['m(QR) > m(TU)', 'm(US) > m(UP)', 'm(SR) > m(QR)', 'm(TU) > m(US)'],
  'La diagonal de un cuadrado mide lado × √2.', 'publicada', 'modelo', '032dec16dba25dc28d8fb3c1433175f6', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('12dbd5e2-73e6-4fcd-ad7a-ddfe7435485c', 3, 'Si el primer cuadrado tiene lado a, PR y TU miden a√2. El segmento US mide a. Por tanto TU > US. Además QR=SR=a y UP=a√2.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'bc46a8b0-bb78-4c2f-a1ac-6d0b99de11b9', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  'c44f65cb-31d8-4a8d-905c-e4ab23849117', 'Interpretación de datos',
  '¿Cuáles afirmaciones describen las correlaciones de la tabla?',
  array['3 y 4.', '1 y 4.', '2 y 3.', '1 y 2.'],
  'Correlación describe el patrón observado; no demuestra que una variable cause la otra.', 'publicada', 'modelo', 'dba9494e767586c028f6960245f8116e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('bc46a8b0-bb78-4c2f-a1ac-6d0b99de11b9', 3, 'Al subir la intensidad de 3 a 12, matemáticas sube de 3,9 a 4,8. Al subir las tareas de 1 a 8, matemáticas baja de 4,8 a 3,9. Las afirmaciones sobre química o sobre ambas materias simultáneamente no coinciden con la tabla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '127bbbc8-a102-4393-8f4b-bdc716777b9a', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  'eff068fd-14eb-4adf-ac6d-006714715ed4', 'Estadística descriptiva',
  'De las calificaciones podemos decir que',
  array['Las de Claudia son más homogéneas pues su desviación estándar es menor.', 'Las de Carlos son más homogéneas pues su desviación estándar es mayor.', 'Las de Miguel son más heterogéneas que las de Carlos.', 'Las de Claudia son más heterogéneas que las de Miguel.'],
  'Homogeneidad y dispersión varían en sentidos contrarios.', 'publicada', 'modelo', '85bd32db945363d3b950e1b3f9910843', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('127bbbc8-a102-4393-8f4b-bdc716777b9a', 0, 'Menor desviación estándar significa menor dispersión y mayor homogeneidad. Claudia tiene la menor, 1; Carlos tiene la mayor, 4.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7cb6ef6f-1e90-4f8b-b3ba-64903eaecfe7', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'tablas-y-probabilidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '1c76bc72-f194-4bdc-a180-cfcd3877d933', 'Tablas y probabilidad',
  'Selecciona el diagrama correspondiente.',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/de1-q30-a.webp" alt="Solo fútbol 55; ambos 38; solo baloncesto 46; ninguno 19." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q30-b.webp" alt="Solo fútbol 36; ambos 19; solo baloncesto 27; ninguno 19." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q30-c.webp" alt="Solo fútbol 17; ambos 38; solo baloncesto 8; ninguno 19." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q30-d.webp" alt="Dos grupos separados: fútbol 55 y baloncesto 46; ninguno 19." loading="lazy"></figure>'],
  'Resta la intersección de cada total antes de escribir las regiones exclusivas.', 'publicada', 'modelo', '7f5ff6ced56ee118f1d47180e544b80a', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7cb6ef6f-1e90-4f8b-b3ba-64903eaecfe7', 2, 'La intersección es 2×19 = 38. Solo fútbol: 55−38=17; solo baloncesto: 46−38=8. Al sumar regiones disjuntas: 17+38+8+19=82.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1643a01c-c3b8-40ce-8ea0-7f2e9fc87c73', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'tablas-y-probabilidad'),
  (select id from public.lotes where codigo = '2026-B'),
  'f559eb3c-d284-439c-8a4c-e9ac1c839cfd', 'Tablas y probabilidad',
  '¿Qué árbol ilustra los posibles resultados?',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/de1-q31-a.webp" alt="Árbol incompleto: solo se desarrollan algunos resultados del tercer giro." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q31-b.webp" alt="Árbol que termina antes de desarrollar las ramas del tercer giro." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q31-c.webp" alt="Desde 2 se pasa a 4 o 1; desde 4 a 8 o 3; desde 1 a 2 o 0. En el tercer giro: 8 pasa a 16 o 7; 3 a 6 o 2; 2 a 4 o 1. El 0 se detiene." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/de1-q31-d.webp" alt="Árbol cuya primera pérdida deja dos fichas en vez de una." loading="lazy"></figure>'],
  'Aplica la misma regla a cada nodo y respeta la condición para detenerse.', 'publicada', 'modelo', '50b5b2ce9d80974e2f770a32b58b89be', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1643a01c-c3b8-40ce-8ea0-7f2e9fc87c73', 2, 'Las transiciones son n→2n y n→n−1. El primer giro deja 4 o 1 fichas. Se aplican ambas reglas en cada rama restante, pero la rama que llega a cero se detiene.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '212b4d9a-8a0f-49cf-9c31-e8509a187690', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'tablas-y-probabilidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '2dcd1a2c-de86-435e-bd62-29f163998098', 'Tablas y probabilidad',
  '¿Con cuáles procedimientos puede encontrar la cantidad de mezclas?',
  array['3 y 4.', '2 y 3.', 'Solamente 1.', 'Solamente 3.'],
  'Cuando el orden no cambia el resultado, usa combinaciones.', 'publicada', 'modelo', 'aa8e4d64916179902f6ff963b1652b91', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('212b4d9a-8a0f-49cf-9c31-e8509a187690', 0, 'Escoger colores no depende del orden. Los procedimientos 3 y 4 describen el mismo conteo: C(6,3)=6!/(3!3!)=20. Dividir 6 entre 3 o 6! entre 3 no cuenta los grupos sin orden.');

